<?php

namespace Database\Seeders;

use App\Models\Broadcast;
use App\Models\User;
use Illuminate\Database\Seeder;

class BroadcastSeeder extends Seeder
{
    public function run(): void
    {
        $adminId = User::query()->where('email', UserSeeder::SUPER_ADMIN_EMAIL)->value('id');
        $images = ['/images/broadcasts/broadcast-01.svg', '/images/broadcasts/broadcast-02.svg', '/images/broadcasts/broadcast-03.svg', '/images/broadcasts/broadcast-04.svg', '/images/broadcasts/broadcast-05.svg', '/images/broadcasts/broadcast-06.svg'];

        foreach ($this->rows() as $index => $row) {
            Broadcast::query()->updateOrCreate(
                ['slug' => $row['slug']],
                array_merge($row, [
                    'featured_image' => $images[$index % count($images)],
                    'created_by' => $adminId,
                ]),
            );
        }
    }

